+const STOCK_FILE = new URL("../data/stock.csv", import.meta.url);
+
+async function readStock() {
+  const [header, ...rows] = parseCsv(await readFile(STOCK_FILE, "utf8"));
+  return rows.map((cells) => {
+    const row = Object.fromEntries(header.map((key, i) => [key, cells[i] ?? ""]));
+    return {
+      sku: row.sku,
+      name: row.name,
+      qty: Number(row.qty),
+      unit: row.unit === "" ? null : row.unit,
+      shelf: row.shelf,
+    };
+  });
+}
+
+// RFC 4180 CSV: quoted fields may hold commas, newlines and doubled quotes.
+function parseCsv(text) {
+  const rows = [];
+  let row = [];
+  let field = "";
+  let quoted = false;
+  for (let i = 0; i < text.length; i++) {
+    const c = text[i];
+    if (quoted) {
+      if (c === '"' && text[i + 1] === '"') {
+        field += '"';
+        i++;
+      } else if (c === '"') quoted = false;
+      else field += c;
+    } else if (c === '"') quoted = true;
+    else if (c === ",") {
+      row.push(field);
+      field = "";
+    } else if (c === "\n" || c === "\r") {
+      if (c === "\r" && text[i + 1] === "\n") i++;
+      row.push(field);
+      rows.push(row);
+      row = [];
+      field = "";
+    } else field += c;
+  }
+  if (field !== "" || row.length) {
+    row.push(field);
+    rows.push(row);
+  }
+  return rows.filter((r) => !(r.length === 1 && r[0] === ""));
+}
